#!/usr/bin/env bash
# Download the pinned official XTLS/libXray Apple xcframework.
# Does not embed the binary in git. Does not start a VPN or use profile secrets.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")" && pwd)"
VERSION="v26.11.9"
ASSET="libxray-apple-cgo.zip"
URL="https://github.com/XTLS/libXray/releases/download/${VERSION}/${ASSET}"
SHA256="7c58346709f1856782a48d8f9926fb815c8ad1bbaf9e5d9dec4ee0cd1f41ed6f"
XCFRAMEWORK="${ROOT}/LibXray.xcframework"
LOCAL_XCCONFIG="${ROOT}/LibXray.local.xcconfig"

echo "libXray pin: ${VERSION}"
echo "sha256:      ${SHA256}"
echo "url:         ${URL}"

if [[ "$(uname -s)" != "Darwin" ]]; then
  cat <<'MSG'

This download is the Apple static library (libXray.a slices).
Linking it requires macOS and Xcode. On Linux the tunnel sources still
compile their fail-closed path, and scripts/verify-libxray-config.py can
check generated JSON against the Linux libXray .so of the same release.

MSG
  exit 2
fi

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
curl -fL --retry 3 -o "${TMP}/${ASSET}" "${URL}"

if command -v shasum >/dev/null 2>&1; then
  echo "${SHA256}  ${TMP}/${ASSET}" | shasum -a 256 -c -
else
  echo "${SHA256}  ${TMP}/${ASSET}" | sha256sum -c -
fi

rm -rf "${XCFRAMEWORK}"
unzip -q "${TMP}/${ASSET}" -d "${TMP}/out"
mv "${TMP}/out/libxray-apple-cgo/LibXray.xcframework" "${XCFRAMEWORK}"

cat > "${LOCAL_XCCONFIG}" <<'EOF'
// Generated by fetch-libxray.sh. Gitignored.
// One Go runtime only: link this archive into VpnRealityTunnel, not the app.
LIBXRAY_CONDITION = LIBXRAY_ENABLED
LIBXRAY_HEADER_SEARCH_PATHS[sdk=iphoneos*] = $(PROJECT_DIR)/ThirdParty/LibXray.xcframework/ios-arm64/Headers
LIBXRAY_HEADER_SEARCH_PATHS[sdk=iphonesimulator*] = $(PROJECT_DIR)/ThirdParty/LibXray.xcframework/ios-arm64_x86_64-simulator/Headers
LIBXRAY_LDFLAGS[sdk=iphoneos*] = -Wl,-force_load,$(PROJECT_DIR)/ThirdParty/LibXray.xcframework/ios-arm64/libXray.a -lresolv -lc++ -framework CoreFoundation -framework Security -framework SystemConfiguration -framework Network
LIBXRAY_LDFLAGS[sdk=iphonesimulator*] = -Wl,-force_load,$(PROJECT_DIR)/ThirdParty/LibXray.xcframework/ios-arm64_x86_64-simulator/libXray.a -lresolv -lc++ -framework CoreFoundation -framework Security -framework SystemConfiguration -framework Network
EOF

echo "Installed ${XCFRAMEWORK}"
echo "Wrote ${LOCAL_XCCONFIG}"
echo "Open ios/VpnReality/VpnReality.xcodeproj, set your Team on both targets, then build VpnReality."
echo "Do not also link SwiftyXrayKit or another Go framework into the extension."
